function pfRng(seed){
  var s=(seed>>>0)||1;
  return function(){ s^=s<<13; s>>>=0; s^=s>>17; s^=s<<5; s>>>=0; return s/4294967296; };
}
function pfEmit(mode, x, y, count, rng){
  rng=rng||Math.random;
  var out=[];
  for(var i=0;i<count;i++){
    var a, sp, p;
    if(mode==='fireworks'){
      a=rng()*Math.PI*2; sp=1.5+rng()*3;
      p={ x:x, y:y, vx:Math.cos(a)*sp, vy:Math.sin(a)*sp, life:40+Math.floor(rng()*30), age:0, hue:Math.floor(rng()*360) };
    } else if(mode==='snow'){
      p={ x:rng()*480, y:-4, vx:(rng()-0.5)*0.6, vy:0.4+rng()*0.8, life:400, age:0, hue:200 };
    } else {
      a=-Math.PI/2+(rng()-0.5)*0.6; sp=3+rng()*2.5;
      p={ x:x, y:y, vx:Math.cos(a)*sp, vy:Math.sin(a)*sp, life:70+Math.floor(rng()*40), age:0, hue:180+Math.floor(rng()*80) };
    }
    out.push(p);
  }
  return out;
}
function pfStep(ps, opts){
  opts=opts||{};
  var g=('grav' in opts)?Number(opts.grav):0.12;
  var drag=('drag' in opts)?Number(opts.drag):0.995;
  var w=opts.w||480, h=opts.h||320;
  var out=[];
  for(var i=0;i<ps.length;i++){
    var p=ps[i];
    var vx=p.vx*drag, vy=(p.vy+g)*drag;
    var np={ x:p.x+vx, y:p.y+vy, vx:vx, vy:vy, life:p.life, age:p.age+1, hue:p.hue };
    if(np.age<np.life && np.y<h+8 && np.x>-8 && np.x<w+8) out.push(np);
  }
  return out;
}
function pfAlpha(p){ if(!p||p.life<=0) return 0; var t=1-p.age/p.life; return Math.max(0,Math.min(1,t)); }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { pfRng:pfRng, pfEmit:pfEmit, pfStep:pfStep, pfAlpha:pfAlpha };
}
if (typeof window !== 'undefined') {
  window.ParticleForgePure = { pfRng:pfRng, pfEmit:pfEmit, pfStep:pfStep, pfAlpha:pfAlpha };
}
